css:
.cat-breadcrumb{display:flex;align-items:center;gap:8px;font:400 var(--cat-font-size-base) var(--cat-font-family-ui)}
.cat-breadcrumb .crumb{color:var(--cat-color-ink-low);cursor:pointer;transition:color var(--cat-motion-fast)}
.cat-breadcrumb .crumb:hover{color:var(--cat-color-ink-hi)}
.cat-breadcrumb .crumb.current{color:var(--cat-color-ink-hi);font-weight:600;cursor:default}
.cat-breadcrumb .sep{color:var(--cat-color-ink-faint)}
.cat-toolbar{display:inline-flex;align-items:center;gap:2px;padding:5px 8px;border-radius:var(--cat-size-radius-md);background:var(--cat-semantic-toolbar-bg,var(--cat-color-accent-subtle-b));border:1px solid var(--cat-color-stroke-input);backdrop-filter:blur(var(--cat-blur-chip)) saturate(var(--cat-blur-saturate-chip));-webkit-backdrop-filter:blur(var(--cat-blur-chip)) saturate(var(--cat-blur-saturate-chip));box-shadow:none}
.cat-tool-btn{display:inline-flex;align-items:center;gap:7px;height:32px;padding:0 12px;border-radius:var(--cat-size-radius-sm);border:none;background:none;font:550 var(--cat-font-size-md) var(--cat-font-family-ui);color:var(--cat-color-ink-hi);cursor:pointer;transition:background var(--cat-motion-fast),transform var(--cat-motion-fast)}
.cat-tool-btn:hover{background:rgba(255,255,255,.55)}
.cat-tool-btn:active{transform:scale(.97)}
.cat-tool-btn.primary{font-weight:650}
.cat-tool-btn.primary .plus{display:grid;place-items:center;width:17px;height:17px;border-radius:50%;background:var(--cat-semantic-accent-dynamic,var(--cat-color-accent-base));color:#fff;font-size:11px}
.cat-tool-sep{width:1px;height:18px;margin:0 8px;background:rgba(20,30,60,.10)}
